#!/bin/bash
set -eu
umask 077
export PYTHONDONTWRITEBYTECODE=1
/home/loosqk/.local/share/uv/python/cpython-3.12.13-linux-aarch64-gnu/bin/python3 - <<'PYPREP'
from pathlib import Path
import base64,json,hashlib,time,os
phase=Path('/home/loosqk/robot-checks/position-return-20261010-r1/head-p32-trial-r13')
assert not (phase/'head1-p32-trial-r13').exists() and not (phase/'head1-p32-trial-launch-r13').exists()
data=json.loads(base64.b64decode('',validate=True));refs=[]
for name,value in data.items():
 raw=base64.b64decode(value,validate=True);p=phase/name
 with p.open('xb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
 st=p.stat();refs.append({'path':str(p),'sha256':hashlib.sha256(raw).hexdigest(),'bytes':len(raw),'uid':st.st_uid,'gid':st.st_gid,'mode':st.st_mode&0o777,'inode':st.st_ino,'mtime_ns':st.st_mtime_ns,'ctime_ns':st.st_ctime_ns})
receipt={'status':'R13_NEW_FIELD_GO_UPLOADED_UART_ZERO','recorded_ns':time.time_ns(),'refs':refs,'uart_operations':0,'actions':0}
with (phase/'root-field-go-upload-r13.json').open('x') as f:json.dump(receipt,f,ensure_ascii=False,indent=2);f.write('\n');f.flush();os.fsync(f.fileno())
print(json.dumps(receipt,ensure_ascii=False))
PYPREP
